def test_reads_interleaved_with_writes_obey_consistent_snapshots(self) -> None:
    self.fork()
    threads: list[threading.Thread] = []
    stop = threading.Event()
    violations: list[str] = []

    def writer(worker: int) -> None:
        for index in range(40):
            self.reserve(
                "br-1",
                f"w{worker}-{index}",
                resource_id="pool",
                quantity=1,
                capacity=1000,
            )

    def reader() -> None:
        while not stop.is_set():
            status, body = self.get_resources()
            if status != 200:
                violations.append(f"status {status}")
                return
            rows = body["resources"]
            if [r["resourceId"] for r in rows] != sorted(
                r["resourceId"] for r in rows
            ):
                violations.append("unsorted rows")
            for row in rows:
                if (
                    row["occupied"] + row["remaining"] != row["capacity"]
                    or not (0 <= row["occupied"] <= row["capacity"])
                ):
                    violations.append(f"torn balances: {row}")

    readers = [threading.Thread(target=reader) for _ in range(4)]
    for thread in readers:
        thread.start()
    writers = [
        threading.Thread(target=writer, args=(worker,)) for worker in range(4)
    ]
    for thread in writers:
        thread.start()
    for thread in writers:
        thread.join(timeout=10)
    stop.set()
    for thread in readers:
        thread.join(timeout=5)

    self.assertEqual(violations, [])
    status, body = self.get_resources()
    self.assertEqual(status, 200)
    (row,) = body["resources"]
    self.assertEqual(row["occupied"], 160)
    self.assertEqual(row["remaining"], 840)

